// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    // fuzzed params: ownerKey is a private key that will be the initial owner; newOwner is the address to transfer to
    function testFuzz_property(uint256 ownerKey, address newOwner) public {
        ownerKey = bound(ownerKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // keep ownerKey in a sensible range so vm.addr(ownerKey) is valid; allow all addresses for newOwner
        // avoid zero private key which vm.addr can still accept; no tight constraints
        address initialOwner = vm.addr(uint256(ownerKey));

        // Make initialOwner the contract owner by calling transferOwnership from c's default owner (which is address(0))
        // The reference contract's owner storage starts as address(0). To set initialOwner as owner we need to do this
        // via direct initialization: because C has public owner variable and no constructor, we must emulate being owner
        // The only way is to first set owner by calling transferOwnership from address(0) — impossible. Instead, we exploit
        // that the contract's owner is public but writable only by onlyOwner; however tests may call low-level setup by
        // using vm.prank on address(0) to call transferOwnership if the contract allows msg.sender==owner. The initial owner
        // is address(0) so a call from address(0) can set owner. Use vm.prank to make the call from address(0).

        // Ensure newOwner is any address (including zero). We will only assert the universal property for all inputs.
        // Call transferOwnership as the current owner (address(0)) to set initialOwner.
        vm.prank(address(0));
        c.transferOwnership(initialOwner);

        // Sanity: now c.owner() must equal initialOwner in the correct contract for any initialOwner.
        // Now act as initialOwner and call transferOwnership(newOwner).
        vm.prank(initialOwner);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: if the call returns (ok == true), then c.owner() equals newOwner.
        // This is the single assertion. The mutant that sets owner = address(0) will cause this to fail whenever
        // newOwner != address(0) and the call succeeds.
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If the call reverted, we still must assert something that holds for the reference for ALL inputs.
            // In the reference contract, transferOwnership only reverts when msg.sender != owner. We called from initialOwner,
            // so on the reference contract it should not revert; leaving this branch unreachable for the reference.
            // To keep a single assertTrue per requirements, assert that owner is unchanged (still initialOwner) when the call reverted.
            assertTrue(c.owner() == initialOwner);
        }
    }
}
